classDiagram
direction LR
class DesktopAppShell { +navigate(route) +placeInspector(mode) +restoreFocus() }
class ChatWorkspace { +acceptComposerIntent(intent) +acceptTimelineIntent(intent) +selectEvidence(id) }
class ConversationPresenter { +render(items) +renderUnknown(item) }
class ComposerController { +editDraft(change) +submit(intent) +retainOnFailure() }
class WorkflowEditor { +loadLossless(document) +serializeComplete() +save(baseVersion) }
class EvidenceInspector { +select(evidenceId) +queryPage(cursor) }
class SettingsCapabilityResolution { +editSection(draft) +resolve(referenceId) }
class ManagementRepairReview { +review(candidate) +activateAndRestart(version) }
class UiProjectionGateway { -sequenceCursor -pendingCommands +dispatch(command) +accept(event) +resync() +select(key) }
class EventOrderGate { +classify(sequence) +lastContiguous() }
class ProjectionReducer { <<pure>> +reduce(previous,event) +hydrate(snapshot) }
class CoreCommandPort { <<interface>> +invoke(command) +query(query) }
class CoreEventPort { <<interface>> +subscribe(afterSequence) }
class UiCommand { <<union>> +schemaVersion +commandId +targetVersion +payload }
class CoreEventEnvelope { +streamId +sequence +semanticEventId +kind +schemaVersion +payload }
class FeatureProjection { <<immutable>> +generation +lastSequence +stale }
class DesignSystem { +tokens() +primitive(name) +focusService() +announce(status) }
class WorkbenchPrimitivePort { <<interface>> +menu(actionIds) +splitter(model) +dialog(model) +tree(model) }
class MantineWorkbenchAdapter { <<adapter>> +renderPrimitive(model) +restoreFocus() }
class WorkflowGraphSurfacePort { <<interface>> +render(graphViewModel) +emit(canvasIntent) }
class ReactFlowAdapter { <<adapter>> +renderGraph(viewModel) +translateGesture(intent) }
class CollectionViewPort { <<interface>> +renderTable(viewModel) +renderVirtualList(viewModel) }
class TanStackTableVirtualAdapter { <<adapter>> +renderRows(viewModel) +measureViewport() }
class NativeDesktopUiPort { <<interface>> +installMenu(actions) +requestDialog(intent) +notify(projection) }
class TauriNativeUiAdapter { <<adapter>> +bindNativeMenu() +openNativeDialog() +showNotification() }
DesktopAppShell o-- ChatWorkspace
DesktopAppShell o-- WorkflowEditor
DesktopAppShell o-- SettingsCapabilityResolution
DesktopAppShell o-- ManagementRepairReview
DesktopAppShell o-- EvidenceInspector
ChatWorkspace *-- ConversationPresenter
ChatWorkspace *-- ComposerController
ConversationPresenter --> EvidenceInspector : EvidenceSelection
ConversationPresenter ..> ManagementRepairReview : repair_candidate
DesktopAppShell --> UiProjectionGateway
ChatWorkspace --> UiProjectionGateway
WorkflowEditor --> UiProjectionGateway
EvidenceInspector --> UiProjectionGateway
SettingsCapabilityResolution --> UiProjectionGateway
ManagementRepairReview --> UiProjectionGateway
UiProjectionGateway *-- EventOrderGate
UiProjectionGateway *-- ProjectionReducer
UiProjectionGateway --> CoreCommandPort
UiProjectionGateway --> CoreEventPort
UiProjectionGateway ..> UiCommand
CoreEventPort ..> CoreEventEnvelope
ProjectionReducer ..> CoreEventEnvelope
ProjectionReducer --> FeatureProjection
DesktopAppShell ..> DesignSystem
ChatWorkspace ..> DesignSystem
ConversationPresenter ..> DesignSystem
ComposerController ..> DesignSystem
WorkflowEditor ..> DesignSystem
EvidenceInspector ..> DesignSystem
SettingsCapabilityResolution ..> DesignSystem
ManagementRepairReview ..> DesignSystem
DesktopAppShell --> WorkbenchPrimitivePort
ChatWorkspace --> WorkbenchPrimitivePort
ComposerController --> WorkbenchPrimitivePort
SettingsCapabilityResolution --> WorkbenchPrimitivePort
ManagementRepairReview --> WorkbenchPrimitivePort
WorkflowEditor --> WorkflowGraphSurfacePort
ConversationPresenter --> CollectionViewPort
EvidenceInspector --> CollectionViewPort
DesktopAppShell --> NativeDesktopUiPort
SettingsCapabilityResolution --> NativeDesktopUiPort
MantineWorkbenchAdapter ..|> WorkbenchPrimitivePort
ReactFlowAdapter ..|> WorkflowGraphSurfacePort
TanStackTableVirtualAdapter ..|> CollectionViewPort
TauriNativeUiAdapter ..|> NativeDesktopUiPort
MantineWorkbenchAdapter --> DesignSystem : semantic tokens and roles
ReactFlowAdapter --> DesignSystem : node and focus primitives
TanStackTableVirtualAdapter --> DesignSystem : row and focus primitives
note for UiProjectionGateway "Pure strict TypeScript; no React, Mantine, React Flow, TanStack, or native UI types"
note for WorkbenchPrimitivePort "Features depend on Aworkit view models and action IDs, never toolkit state"
note for WorkflowGraphSurfacePort "Aworkit owns WorkflowDraft, commands, undo, IDs, and serialization"
note for NativeDesktopUiPort "Native choices become typed intents; privileged validation remains in Trusted Core"
class NotificationPort { <<interface>> +publish(notice) +update(id,occurrence,patch) +resolve(id,occurrence) +dismiss(id,occurrence) +clearScope(scope) }
class NotificationStore { -active -recent -expiryTimer +subscribe() +selectPrimary() }
class DesktopStatusBar { +showPrimary() +openDockedDetails() }
class SettingsVisitController { +openSettings(origin) +requestLeave(destination) +restoreView() }
class SettingsReturnContext { +route +entityIdentity +viewAnchors +focusTarget }
DesktopAppShell *-- NotificationStore
DesktopAppShell *-- DesktopStatusBar
DesktopAppShell *-- SettingsVisitController
NotificationStore ..|> NotificationPort
DesktopStatusBar --> NotificationStore : read-only presentation
SettingsVisitController *-- SettingsReturnContext
SettingsVisitController --> SettingsCapabilityResolution : leave guard and visit identity
SettingsCapabilityResolution --> NotificationPort
ChatWorkspace --> NotificationPort
WorkflowEditor --> NotificationPort
ManagementRepairReview --> NotificationPort
note for NotificationStore "Session-only presentation; source owners control relevance; no command retries or authority"
note for SettingsReturnContext "Restore view and drafts; do not rewind current runtime projections"
